/** The complaints register — GET /api/v1/complaints (who may call: holders of complaint.view or complaint.manage or complaint.register). */
export function listComplaints(query?: { status?: "Received" | "Acknowledged" | "Resolved" | "Appealed" | "Closed" | "Withdrawn" | "NotMaintainable" | null; category?: "ClinicalCare" | "NursingCare" | "StaffAttitude" | "Communication" | "WaitingTime" | "Billing" | "Cleanliness" | "Food" | "Facilities" | "Privacy" | "Safety" | "Medication" | "Diagnostics" | "Other" | null; channel?: "InPerson" | "Telephone" | "Letter" | "Email" | "SuggestionBox" | "HealthCommission" | "SocialMedia" | "Other" | null; priority?: "Urgent" | "High" | "Normal" | "Low" | null; department_id?: number | null; patient_id?: number | null; date_from?: string | null; date_to?: string | null; mine?: boolean; open_only?: boolean; overdue_only?: boolean; limit?: number }): Promise<ComplaintOut[]> {
  return api<ComplaintOut[]>("GET", withQuery(`/complaints`, query), undefined);
}

/** One complaint — GET /api/v1/complaints/{complaint_id} (who may call: complaint.view or complaint.manage, the person who received the complaint and its investigator). */
export function getComplaint(complaint_id: number): Promise<ComplaintDetailOut> {
  return api<ComplaintDetailOut>("GET", `/complaints/${complaint_id}`, undefined);
}

/** Write the findings of the investigation — POST /api/v1/complaints/{complaint_id}/findings (who may call: complaint.manage or the complaint's named investigator). */
export function writeFindings(complaint_id: number, body: FindingsIn): Promise<ComplaintDetailOut> {
  return api<ComplaintDetailOut>("POST", `/complaints/${complaint_id}/findings`, body, { idempotent: true });
}

/** Record a contact with the complainant (progress, more time) — POST /api/v1/complaints/{complaint_id}/updates (who may call: complaint.manage or the complaint's named investigator). */
export function recordUpdate(complaint_id: number, body: ComplaintUpdateIn): Promise<ComplaintDetailOut> {
  return api<ComplaintDetailOut>("POST", `/complaints/${complaint_id}/updates`, body, { idempotent: true });
}

/** Record a corrective or preventive action — POST /api/v1/complaints/{complaint_id}/actions (who may call: complaint.manage or the complaint's named investigator). */
export function addActionComplaintsActions(complaint_id: number, body: QualityActionIn): Promise<QualityActionOut> {
  return api<QualityActionOut>("POST", `/complaints/${complaint_id}/actions`, body, { idempotent: true });
}

/** Departments — GET /api/v1/admin/departments (who may call: any logged-in user). */
export function departments(): Promise<DepartmentOut[]> {
  return api<DepartmentOut[]>("GET", `/admin/departments`, undefined);
}

/** Find a staff member for a form (badge facts only) — GET /api/v1/staff/lookup (who may call: any logged-in user). */
export function lookupStaff(query: { q: string; department_id?: number | null; license_type?: "PMDC" | "PNC" | null; limit?: number }): Promise<StaffLookupOut[]> {
  return api<StaffLookupOut[]>("GET", withQuery(`/staff/lookup`, query), undefined);
}
